"""Render docs/configuration.md from the schema so docs cannot drift from code."""
from .schema import FIELDS

HEAD = """# Configuration reference

<!-- Generated by `python percept config-doc --write`. Edit src/percept/schema.py, not this file. -->

Each board lives in `boards/<name>/`:

- `board.toml`: settings you can share when asking for help.
- `secrets.toml`: password hashes, the Wi-Fi passphrase. **Never share.** Git-ignored.

`python percept configure` writes both for you. You can also edit them by hand and
check them with `python percept validate --board <name>`. Both files are merged;
any setting may be in either. A secret setting `x` may instead be given as
`x_file = "path"` or `x_env = "VARIABLE"` so it never sits in a file in your checkout.

Nothing in `boards/` is ever committed, uploaded or put in a release. Plaintext
passwords are never stored: only `$6$` hashes (`python percept hash-password`).

Examples: [`examples/board.minimal.toml`](../examples/board.minimal.toml),
[`examples/board.full.toml`](../examples/board.full.toml).

"""


def _default(f):
    if f.default is None:
        return "-" if f.type != "str" else "(none)"
    if isinstance(f.default, bool):
        return "`true`" if f.default else "`false`"
    if isinstance(f.default, list):
        return "`[%s]`" % ", ".join('"%s"' % x for x in f.default) if f.default else "`[]`"
    return "`%s`" % f.default


def render():
    out = [HEAD]
    section = None
    for f in FIELDS:
        head = f.path.rsplit(".", 1)[0] if "." in f.path else "(top level)"
        if head != section:
            section = head
            title = "[[%s]]" % head.replace("[]", "") if head.endswith("[]") else "[%s]" % head if head != "(top level)" else head
            out.append("\n## `%s`\n\n| Setting | Type | Default | Secret | Meaning |\n|---|---|---|---|---|\n" % title
                       if head != "(top level)" else "\n## Top level\n\n| Setting | Type | Default | Secret | Meaning |\n|---|---|---|---|---|\n")
        key = f.path.rsplit(".", 1)[-1]
        out.append("| `%s` | %s | %s | %s | %s |\n" % (key, f.type, _default(f), "yes" if f.secret else "", f.doc))
    return "".join(out).replace("\n\n\n", "\n\n")
